def rotate_left(values, k):
    if not values:
        return []
    n = len(values)
    k = k % n
    return values[k:] + values[:k]

def balanced(text):
    stack = []
    for char in text:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

def runs(values):
    if not values:
        return []

    result = []
    current_value = values[0]
    current_count = 1

    for i in range(1, len(values)):
        if values[i] == current_value:
            current_count += 1
        else:
            result.append([current_value, current_count])
            current_value = values[i]
            current_count = 1

    result.append([current_value, current_count])
    return result

def merge_counts(a, b):
    result = {}
    for key, count in a.items():
        result[key] = count
    for key, count in b.items():
        result[key] = result.get(key, 0) + count
    return result

def longest_word(words):
    if not words:
        return None
    return max(words, key=len)
